    assert linear_feet_for_shipment([PalletLine(4, height_in=60, stackable=True)]) == 8


def test_wide_pallets_load_one_across():
    assert linear_feet_for_shipment([PalletLine(3, length_in=60, width_in=52)]) == 15


def test_different_footprints_do_not_share_rows():
    lines = [PalletLine(1), PalletLine(1, length_in=48, width_in=45)]
    assert linear_feet_for_shipment(lines) == 8


def test_empty_shipment_is_rejected():
    with pytest.raises(ValueError):
        linear_feet_for_shipment([])


def test_zero_pallet_count_is_rejected():
    with pytest.raises(ValueError):
        linear_feet_for_shipment([PalletLine(0)])


def test_negative_pallet_count_is_rejected():
    with pytest.raises(ValueError):
        linear_feet_for_shipment([PalletLine(-3)])


def test_shipment_over_trailer_length_is_rejected():
    # 28 pallets at two per row fill 14 rows of 48" = 56 ft, past the 53' limit.
    with pytest.raises(ValueError):
        linear_feet_for_shipment([PalletLine(28)])


def test_shipment_filling_trailer_is_allowed():
    # 26 pallets at two per row fill 13 rows of 48" = 52 ft, inside the limit.
    assert linear_feet_for_shipment([PalletLine(26)]) == 52

