washout_fee.py:
"""Trailer washout reimbursement for contaminated equipment after delivery.

A washout is reimbursable only when the delivered commodity leaves the trailer needing
cleaning for the next load. The settlement service uses the rules below to decide how
much of a carrier-submitted wash receipt may be passed through to the customer.

Business rules:
- The required wash level is driven by the stronger of the commodity contamination
  class and the next-load requirement supplied by operations.
- Wash levels bill at contract maximums: rinse, standard, sanitize, and hazmat.
- Contracts may disallow pass-through entirely, or may disallow premium hazmat
  reimbursement even when a hazmat wash was operationally required.
- The reimbursable amount is the lesser of the actual receipt and the allowed maximum,
  reduced by any carrier deductible, then rounded to cents.
- Receipts at or below the deductible reimburse zero. Negative receipts and invalid
  combinations are rejected.
- Food-grade commodities require at least a sanitize wash.
- Non-contaminating dry freight does not reimburse unless operations explicitly require
  a wash for the next load.
"""

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal

CENT = Decimal("0.01")

_LEVEL_ORDER = {"none": 0, "rinse": 1, "standard": 2, "sanitize": 3, "hazmat": 4}
_CLASS_MINIMUM = {
    "dry": "none",
    "produce": "rinse",
    "food": "sanitize",
    "chemical": "standard",
    "hazmat": "hazmat",
}
_MAX_BY_LEVEL = {
    "none": Decimal("0.00"),
    "rinse": Decimal("35.00"),
    "standard": Decimal("85.00"),
    "sanitize": Decimal("140.00"),
    "hazmat": Decimal("225.00"),
}


@dataclass(frozen=True)
class WashoutRequest:
    commodity_class: str
    required_wash_level: str
    receipt_amount: Decimal
    food_grade_trailer: bool = False


@dataclass(frozen=True)
class PassThroughTerms:
    allow_pass_through: bool = True
    allow_hazmat_premium: bool = True
    carrier_deductible: Decimal = Decimal("15.00")
    customer_cap: Decimal | None = None


def _validate(request: WashoutRequest, terms: PassThroughTerms) -> None:
    if request.commodity_class not in _CLASS_MINIMUM:
        raise ValueError(f"unknown commodity_class: {request.commodity_class}")
    if request.required_wash_level not in _LEVEL_ORDER:
        raise ValueError(f"unknown required_wash_level: {request.required_wash_level}")
    if request.receipt_amount <= 0:
        raise ValueError("receipt_amount cannot be negative")
    if terms.carrier_deductible < 0:
        raise ValueError("carrier_deductible cannot be negative")
    if terms.customer_cap is not None and terms.customer_cap < 0:
        raise ValueError("customer_cap cannot be negative")


def _stronger_level(left: str, right: str) -> str:
    return left if _LEVEL_ORDER[left] >= _LEVEL_ORDER[right] else right


def _required_level(request: WashoutRequest) -> str:
    level = _stronger_level(_CLASS_MINIMUM[request.commodity_class], request.required_wash_level)
    if request.food_grade_trailer and _LEVEL_ORDER[level] < _LEVEL_ORDER["sanitize"]:
        return "sanitize"
    return level


def _allowed_maximum(level: str, terms: PassThroughTerms) -> Decimal:
    if not terms.allow_pass_through:
        return Decimal("0.00")
    if level == "hazmat" and not terms.allow_hazmat_premium:
        # The contract blocks the hazmat premium, but a regular wash of the
        # contaminated trailer remains reimbursable up to the standard limit.
        return _MAX_BY_LEVEL["standard"]
    return _MAX_BY_LEVEL[level]


def _apply_cap(amount: Decimal, cap: Decimal | None) -> Decimal:
    if cap is not None and amount > cap:
        return cap
    return amount


def calculate_washout_fee(
    request: WashoutRequest, terms: PassThroughTerms = PassThroughTerms()
) -> Decimal:
    """Reimbursable washout amount in dollars, rounded to the cent.

    The payable amount is limited by the required wash level, contract settings,
    optional customer cap, and the carrier deductible.
    """
    _validate(request, terms)
    level = _required_level(request)
    if level == "none":
        return Decimal("0.00")

    allowed = _allowed_maximum(level, terms)
    allowed = _apply_cap(allowed, terms.customer_cap)
    eligible = min(request.receipt_amount, allowed)
    if eligible <= terms.carrier_deductible:
        return Decimal("0.00")

    reimbursable = eligible - terms.carrier_deductible
    return reimbursable.quantize(CENT, rounding=ROUND_HALF_UP)

axle_weights.py:
"""Federal axle weight checks for a loaded tractor-trailer (23 CFR 658.17).

Load planning runs ``check_axle_weights`` on the scale ticket or the planned axle
loads before a truck is dispatched onto the Interstate. The federal limits:

- 20,000 lbs on any single axle.
- 34,000 lbs on a tandem (two axles more than 40" and at most 96" apart).
- 80,000 lbs gross.
- The bridge formula, W = 500 * (L*N/(N-1) + 12*N + 36), on every group of two or
  more consecutive axles: N is the number of axles in the group, L the distance
  in feet between its outer axles, W the most the group may carry. Like the
  published bridge table, W is rounded to the nearest 500 lbs. A group that is
  just one tandem is covered by the tandem limit instead.
- Exception: two consecutive tandems may carry 34,000 lbs each (68,000 together)
  if their outer axles are 36 feet or more apart, even when the formula gives
  less.

Axles are given front to back, with positions in feet from the steer axle.
"""

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal

SINGLE_LIMIT = 20_000
TANDEM_LIMIT = 34_000
GROSS_LIMIT = 80_000
TANDEM_MAX_SPACING_FT = 8.0
DOUBLE_TANDEM_MIN_SPAN_FT = 36.0
DOUBLE_TANDEM_LIMIT = 68_000


@dataclass(frozen=True)
class Violation:
    rule: str  # "single", "tandem", "gross" or "bridge"
    first_axle: int
    last_axle: int
    weight: int
    limit: int


def bridge_limit(span_ft: float, axles: int) -> int:
    """The bridge formula for ``axles`` axles spread over ``span_ft`` feet."""
    if axles < 2:
        raise ValueError("the bridge formula needs at least two axles")
    raw = 500 * (Decimal(str(span_ft)) * axles / (axles - 1) + 12 * axles + 36)
    return int((raw / 500).quantize(Decimal(1), rounding=ROUND_HALF_UP) * 500)


def _tandem_starts(positions: list[float]) -> set[int]:
    """Indexes of axles that are the front axle of a tandem."""
    return {
        i for i in range(len(positions) - 1)
        if positions[i + 1] - positions[i] <= TANDEM_MAX_SPACING_FT
    }


def _bridge_spans(axle_count: int, tandems: set[int]) -> list[tuple[int, int]]:
    """Every group of two or more consecutive axles, except lone tandems."""
    return [
        (first, last)
        for first in range(axle_count)
        for last in range(first + 1, axle_count)
        if not (last == first + 1 or first in tandems)
    ]


def _span_limit(first: int, last: int, positions: list[float], tandems: set[int]) -> int:
    span = positions[last] - positions[first]
    limit = bridge_limit(span, last - first + 1)
    double_tandem = last - first == 3 and first in tandems and first + 2 in tandems
    if double_tandem and span >= DOUBLE_TANDEM_MIN_SPAN_FT:
        limit = max(limit, DOUBLE_TANDEM_LIMIT)
    return limit


def check_axle_weights(weights: list[int], positions: list[float]) -> list[Violation]:
    """Every federal limit the axle loads break; an empty list means legal."""
    if len(weights) != len(positions) or len(weights) < 2:
        raise ValueError("need a weight and a position for each of at least two axles")
    if any(b <= a for a, b in zip(positions, positions[1:])):
        raise ValueError("axle positions must increase front to back")
    tandems = _tandem_starts(positions)
    in_tandem = tandems | {i + 1 for i in tandems}
    violations = []
    for i, weight in enumerate(weights):
        if i not in in_tandem and weight > SINGLE_LIMIT:
            violations.append(Violation("single", i, i, weight, SINGLE_LIMIT))
    for i in sorted(tandems):
        weight = weights[i] + weights[i + 1]
        if weight > TANDEM_LIMIT:
            violations.append(Violation("tandem", i, i + 1, weight, TANDEM_LIMIT))
    gross = sum(weights)
    if gross > GROSS_LIMIT:
        violations.append(Violation("gross", 0, len(weights) - 1, gross, GROSS_LIMIT))
    for first, last in _bridge_spans(len(weights), tandems):
        weight = sum(weights[first:last + 1])
        limit = _span_limit(first, last, positions, tandems)
        if weight > limit:
            violations.append(Violation("bridge", first, last, weight, limit))
    return violations

